const visual = {
  prepare: function (input) {
    var labels = ['0', '0.25', '0.5', '0.75', '1'];
    var reqs = [];
    for (var i = 0; i < labels.length; i++) {
      reqs.push({ kind: 'text', payload: labels[i] });
    }
    return reqs;
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var labels = ['0', '0.25', '0.5', '0.75', '1'];
    var pad = Math.max(44, Math.round(w * 0.08));
    var x0 = pad;
    var x1 = w - pad;
    var y = Math.round(h * 0.52);
    var stroke = '#26354a';
    var paths = [];
    var children = [];

    paths.push({ id: 'axis', commands: visualSdk.polyline([[x0, y], [x1, y]]) });
    children.push({ type: 'path', pathId: 'axis', stroke: stroke, strokeWidth: 2, fill: 'none' });

    var xs = [];
    for (var i = 0; i < 5; i++) {
      var x = x0 + (x1 - x0) * i / 4;
      xs.push(x);
      var id = 'tick' + i;
      paths.push({ id: id, commands: visualSdk.polyline([[x, y - 7], [x, y + 7]]) });
      children.push({ type: 'path', pathId: id, stroke: stroke, strokeWidth: 2, fill: 'none' });
    }

    for (var j = 0; j < 5; j++) {
      children.push({
        type: 'label',
        text: labels[j],
        x: xs[j],
        y: y + 30,
        textAnchor: 'middle',
        fontSize: 14,
        fill: stroke
      });
    }

    return {
      schemaVersion: 1,
      sceneId: 'axis-0-1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
